import { Cliente } from "@/app/mock/cliente"
import { useState } from "react"
import Link from "next/link";
import { format } from "path";
 
export default function ClientesForm(){

    const [clientes,setClientes] = useState<Cliente>(new Cliente(0,'','','',true))

    
    const handleChange = (campo:'nome'|'cpf'|'telefone', valor:string)=>{
        setClientes( prev=>
            new Cliente (
                prev.codigo,
                campo === 'nome' ? valor : prev.nome,
                campo === 'cpf' ? valor : prev.nome,
                campo === 'telefone' ? valor : prev.nome,
                prev.ativo
            )
        ) 
    }

    const handleSalvar = (formData : FormData) => {

    }

    return(
        <form action={handleSalvar}>
            <div>
                <div>
                    <label>Nome completo:</label>
                    <input required value={clientes.nome} type="text" onChange={(e)=>{handleChange('nome',e.target.value)}} placeholder="Digite seu nome" />
                </div>
                <div>
                    <label>CPF:</label>
                    <input required value={clientes.cpf} type="text" maxLength={14} onChange={(e)=>{handleChange('cpf',e.target.value)}} placeholder="000.000.000-00" />
                </div>
                <div>
                    <label>Telefone:</label>
                    <input required value={clientes.telefone} type="text" onChange={(e)=>{handleChange('telefone',e.target.value)}} placeholder="(00) 0000-0000" />
                </div>
                
                <div>
                    <Link href="/clientes">Cancelar</Link>
                    <button type="submit">Salvar</button>
                </div>
            </div>
        </form>
    )
}